var ENCSET=new Set(ENC);
var SCOPE=new URL(self.registration.scope).pathname;
var MIME={html:'text/html; charset=utf-8',js:'text/javascript; charset=utf-8',json:'application/json',css:'text/css',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',svg:'image/svg+xml',woff2:'font/woff2',webp:'image/webp',gif:'image/gif',txt:'text/plain; charset=utf-8'};

function tell(msg){return self.clients.matchAll({includeUncontrolled:true}).then(function(cs){cs.forEach(function(c){c.postMessage(msg)})})}
function db(){return new Promise(function(ok,ko){var r=indexedDB.open('opc-licence',1);r.onupgradeneeded=function(){r.result.createObjectStore('k')};r.onsuccess=function(){ok(r.result)};r.onerror=function(){ko(r.error)}})}
function getKey(){return db().then(function(d){return new Promise(function(ok){var t=d.transaction('k').objectStore('k').get('aes');t.onsuccess=function(){ok(t.result||null)};t.onerror=function(){ok(null)}})}).catch(function(){return null})}
function dropKey(){return db().then(function(d){return new Promise(function(ok){var t=d.transaction('k','readwrite');t.objectStore('k').delete('aes');t.oncomplete=ok;t.onerror=ok})}).catch(function(){})}

// install: only the small shell, so the licence screen works at once
self.addEventListener('install',function(e){
  self.skipWaiting();
  e.waitUntil(caches.open(CACHE).then(function(c){return Promise.all(PUBLIC.map(function(f){return fetch(f,{cache:'no-cache'}).then(function(r){if(r.ok)return c.put(f,r)}).catch(function(){})}))}));
});
self.addEventListener('activate',function(e){
  e.waitUntil(caches.keys().then(function(ks){return Promise.all(ks.filter(function(k){return k.indexOf('opc-')===0&&k!==CACHE}).map(function(k){return caches.delete(k)}))}).then(function(){return self.clients.claim()}));
});

// the pages ask for the full download on every launch; files already kept are skipped
var running=null;
function precache(){
  if(running)return running;
  running=caches.open(CACHE).then(function(c){
    var list=ENC.map(function(f){return f+'.enc'}),n=0,failed=0,i=0,total=list.length,todo=0;
    function next(){
      if(i>=total)return Promise.resolve();
      var f=list[i++];
      return c.match(f).then(function(hit){if(hit)return;todo++;return fetch(f,{cache:'no-cache'}).then(function(r){if(!r.ok)throw 0;return c.put(f,r)})})
        .catch(function(){failed++}).then(function(){n++;if(todo&&(n%10===0||n===total))tell({type:'opc-cache',n:n,total:total});return next()});
    }
    return Promise.all([next(),next(),next(),next(),next(),next()]).then(function(){if(todo)return tell({type:'opc-cache',done:true,failed:failed})});
  }).then(function(){running=null},function(){running=null});
  return running;
}
self.addEventListener('message',function(e){if(e.data==='precache')e.waitUntil(precache())});

function serveEnc(rel,req){
  return getKey().then(function(key){
    if(!key)return locked(req);
    return caches.open(CACHE).then(function(c){
      var f=SCOPE+rel+'.enc';
      return c.match(f).then(function(hit){return hit||fetch(f).then(function(r){if(r.ok)c.put(f,r.clone());return r})});
    }).then(function(r){
      if(!r.ok)return new Response('introuvable',{status:404});
      return r.arrayBuffer().then(function(buf){
        return crypto.subtle.decrypt({name:'AES-GCM',iv:new Uint8Array(buf,0,12)},key,new Uint8Array(buf,12)).then(function(plain){
          var ext=(rel.split('.').pop()||'').toLowerCase();
          return new Response(plain,{status:200,headers:{'Content-Type':MIME[ext]||'application/octet-stream'}});
        },function(){return dropKey().then(function(){return locked(req)})});
      });
    });
  });
}
function locked(req){
  if(req.mode==='navigate')return Response.redirect(SCOPE+'index.html',302);
  return new Response('catalogue verrouillé',{status:403});
}

self.addEventListener('fetch',function(e){
  if(e.request.method!=='GET')return;
  var u=new URL(e.request.url);
  if(u.origin!==location.origin||u.pathname.indexOf(SCOPE)!==0)return;
  var rel=decodeURIComponent(u.pathname.slice(SCOPE.length));
  if(rel===''||rel.slice(-1)==='/')rel+='index.html';
  if(ENCSET.has(rel)){e.respondWith(serveEnc(rel,e.request));return}
  e.respondWith(caches.open(CACHE).then(function(c){
    return c.match(rel,{ignoreSearch:true}).then(function(hit){
      return hit||fetch(e.request).then(function(r){if(r.ok&&PUBLIC.indexOf(rel)>=0)c.put(rel,r.clone());return r});
    });
  }));
});
